using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading;
using System.Web.Script.Serialization;
using VirgilPatch;
class MigrationTests {
 static string root;static int passed;static JavaScriptSerializer js=new JavaScriptSerializer();
 const string Key="Test(3.2.0)",Canonical="Test(5.0.0)";
 static byte[] B(string value){return Encoding.UTF8.GetBytes(value);}
 static void Assert(bool ok,string reason){if(!ok)throw new Exception(reason);}
 static void Test(string name,Action test){test();passed++;Console.WriteLine("PASS "+name);}
 static State Fresh(){string area=Path.Combine(root,Guid.NewGuid().ToString("N"));Config.StateDir=Path.Combine(area,"state");var s=new State{patches_dir=Path.Combine(area,"Patches")};Directory.CreateDirectory(s.patches_dir);return s;}
 static RepairSource Source(){var source=new RepairSource();var files=new Dictionary<string,object>();var list=new List<object>();int id=123;foreach(string name in new[]{"a.ogg","b.ogg"}){byte[] data=B("latest-"+name);source.Data["patches/"+Canonical+"/"+name]=data;files[name]=RepairSource.Info(data,id);list.Add(new{file=name,id=id++});}byte[] meta=B(js.Serialize(new{name=Canonical,version="5.0.0",files=list}));source.Data["patches/"+Canonical+"/patch.json"]=meta;source.Data["index.json"]=B(js.Serialize(new{format=2,published="migration",patches=new Dictionary<string,object>{{Key,new{version="5.0.0",repo_dir="patches/"+Canonical,files=files,patch_json=RepairSource.Info(meta)}}}}));return source;}
 static string Seed(State state,string name,string version,string a="latest-a.ogg",string b="latest-b.ogg") {string dir=Path.Combine(state.patches_dir,name);Directory.CreateDirectory(dir);if(a!=null)File.WriteAllText(Path.Combine(dir,"a.ogg"),a);if(b!=null)File.WriteAllText(Path.Combine(dir,"b.ogg"),b);File.WriteAllText(Path.Combine(dir,"patch.json"),js.Serialize(new{name=name,version=version,files=new[]{new{file="a.ogg",id=123},new{file="b.ogg",id=124}}}));return dir;}
 static void Apply(Updater updater){var plan=updater.Check(new[]{Key});updater.Apply(plan,CancellationToken.None);}
 static void Complete(State state){string dir=Path.Combine(state.patches_dir,Canonical);Assert(File.ReadAllText(Path.Combine(dir,"a.ogg"))=="latest-a.ogg"&&File.ReadAllText(Path.Combine(dir,"b.ogg"))=="latest-b.ogg","Latest payload not retained");var meta=js.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(dir,"patch.json")));Assert((string)meta["version"]=="5.0.0","Metadata not finalized");Assert(state.installed.ContainsKey(Key+"/a.ogg"),"Stable tracking keys lost");}
 static int Main(string[] args){try{root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);
 Test("check-and-cancel-make-no-folder-changes",delegate{var s=Fresh();string old=Seed(s,Key,"4.0.0");var u=new Updater(Source(),s);var p=u.Check(new[]{Key});Assert(p.Fetch.Count==0&&!p.UpToDate&&p.Migrations.Count==1,"Migration not planned");Assert(Directory.Exists(old)&&!Directory.Exists(Path.Combine(s.patches_dir,Canonical)),"Check renamed a folder");Assert(PatchDialogs.Summary(p).Contains("Rename / reconcile"),"Preview hides migration");var cancel=new CancellationTokenSource();cancel.Cancel();try{u.Apply(p,cancel.Token);}catch(OperationCanceledException){}Assert(Directory.Exists(old),"Cancelled plan moved files");});
 Test("rename-in-place-preserves-unmanaged-files-and-is-idempotent",delegate{var s=Fresh();string old=Seed(s,Key,"4.0.0");File.WriteAllText(Path.Combine(old,"development.txt"),"keep");var source=Source();var u=new Updater(source,s);Apply(u);Complete(s);Assert(!Directory.Exists(old)&&source.Downloads.Count==0,"Rename redownloaded assets or left alias");Assert(File.ReadAllText(Path.Combine(s.patches_dir,Canonical+"/development.txt"))=="keep","Unmanaged file lost");Assert(u.Check(new[]{Key}).UpToDate,"Migration repeats");});
 Test("newer-misnamed-folder-and-complementary-duplicate-avoid-downloads",delegate{var s=Fresh();Seed(s,Key,"4.0.0","latest-a.ogg",null);Seed(s,"Test(4.0.0)","3.0.0","old-a","latest-b.ogg");var source=Source();var u=new Updater(source,s);var p=u.Check(new[]{Key});Assert(p.Fetch.Count==0,"Reusable duplicate asset planned for download");u.Apply(p,CancellationToken.None);Complete(s);Assert(source.Downloads.Count==0,"Reused files downloaded");Assert(Directory.GetDirectories(s.patches_dir).Select(Path.GetFileName).SequenceEqual(new[]{Canonical}),"Duplicate active folders remain");string backup=Path.Combine(Path.GetDirectoryName(s.patches_dir),"VirgilPatch-Migration-Backups");Assert(Directory.GetFiles(backup,"patch.json",SearchOption.AllDirectories).Length==1,"Rollback duplicate not preserved");});
 Test("existing-canonical-older-content-replaced-with-verified-newer-copy",delegate{var s=Fresh();Seed(s,Canonical,"3.0.0","outdated-a","latest-b.ogg");Seed(s,Key,"4.0.0","latest-a.ogg","outdated-b");Seed(s,"Test(4.0.0)","2.0.0","bad-a","bad-b");var source=Source();var u=new Updater(source,s);Apply(u);Complete(s);Assert(source.Downloads.Count==0,"Merged copies downloaded");Assert(Directory.GetDirectories(s.patches_dir).Length==1,"Duplicate cleanup failed");});
 Test("failure-keeps-duplicates-and-metadata-for-retry",delegate{var s=Fresh();Seed(s,Canonical,"3.0.0","old-a","old-b");string old=Seed(s,Key,"4.0.0","latest-a.ogg","bad-b");string meta=File.ReadAllText(Path.Combine(s.patches_dir,Canonical+"/patch.json"));var source=Source();source.FailAll=true;var u=new Updater(source,s);bool failed=false;try{Apply(u);}catch(Exception){failed=true;}Assert(failed&&Directory.Exists(old),"Failed migration removed recovery source");Assert(File.ReadAllText(Path.Combine(s.patches_dir,Canonical+"/patch.json"))==meta,"Incomplete patch advertised");source.FailAll=false;Apply(new Updater(source,s));Complete(s);Assert(!Directory.Exists(old),"Retry left duplicate");});
 Test("unselected-and-unrelated-folders-untouched",delegate{var s=Fresh();Seed(s,Key,"4.0.0");string unrelated=Seed(s,"Other(4.0.0)","4.0.0");File.WriteAllText(Path.Combine(unrelated,"keep.txt"),"untouched");var source=Source();Apply(new Updater(source,s));Assert(File.ReadAllText(Path.Combine(unrelated,"keep.txt"))=="untouched","Unrelated package changed");Assert(Directory.Exists(unrelated),"Unrelated folder removed");});
 Test("new-updater-instance-can-apply-checked-plan",delegate{var s=Fresh();Seed(s,Key,"4.0.0");var source=Source();var p=new Updater(source,s).Check(new[]{Key});new Updater(source,s).Apply(p,CancellationToken.None);Complete(s);Assert(source.Downloads.Count==0,"Plan lost reuse mapping");});
 Test("new-installs-and-future-revisions-keep-baseline-folder",delegate{var s=Fresh();var source=Source();var u=new Updater(source,s);Apply(u);Complete(s);Assert(!Directory.Exists(Path.Combine(s.patches_dir,Key)),"New install used legacy name");int downloads=source.Downloads.Count;var index=StrictJson.Read(source.Data["index.json"],100000);var entry=(Dictionary<string,object>)((Dictionary<string,object>)index["patches"])[Key];entry["version"]="5.0.0.1";entry["repo_dir"]="patches/Test(5.0.0.1)";foreach(string name in new[]{"a.ogg","b.ogg","patch.json"})source.Data["patches/Test(5.0.0.1)/"+name]=source.Data["patches/"+Canonical+"/"+name];source.Data["index.json"]=B(js.Serialize(index));Apply(new Updater(source,s));Assert(source.Downloads.Count==downloads&&Directory.GetDirectories(s.patches_dir).Length==1,"Revision renamed/redownloaded baseline folder");});
 Test("persisted-map-preserves-repair-and-retired-package-removal",delegate{var s=Fresh();Seed(s,Key,"4.0.0");var source=Source();Apply(new Updater(source,s));var loaded=State.Load();Assert(loaded.install_folders[Key]==Canonical,"Folder map not persisted");string path=Path.Combine(s.patches_dir,Canonical+"/a.ogg");File.Delete(path);Apply(new Updater(source,loaded));Assert(File.Exists(path),"Repair after restart lost renamed folder");source.Publish(new Dictionary<string,Dictionary<string,byte[]>>());var u=new Updater(source,loaded);u.Apply(u.Check(),CancellationToken.None);Assert(!Directory.Exists(Path.Combine(s.patches_dir,Canonical)),"Retired canonical folder remained");});
 Test("tampered-persisted-folder-map-cannot-redirect-files",delegate{var s=Fresh();s.install_folders[Key]="../outside";var u=new Updater(Source(),s);string path=u.Local(Key+"/a.ogg");Assert(path.StartsWith(s.patches_dir+Path.DirectorySeparatorChar),"State mapping escaped selected root");});
 Test("unsafe-package-identities-rejected-before-migration",delegate{var s=Fresh();bool rejected=false;try{FolderMigration.Discover(s,"../Test",Canonical);}catch(InvalidDataException){rejected=true;}Assert(rejected,"Traversal accepted");});
 Console.WriteLine("TOTAL "+passed+" migration cases passed");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
}
